CREATE TABLE OPERATIONS.METER_READING
(
 METER_READING_ID   varchar(30) NOT NULL COMMENT 'Primary key for meter reading.',
 ADDRESS            string NOT NULL,
 METER_ID           varchar(20) NOT NULL COMMENT 'Foreign key to Meter.',
 READING_DATETIME   datetime NOT NULL COMMENT 'Date and time of meter reading.',
 READING_VALUE      decimal(12,3) NOT NULL COMMENT 'Meter reading value (consumption in cubic meters).',
